def _baseline_campaign_policy(self, diagnostics):
    """Return action/task/reason from diagnostics; this seed is intentionally weak."""
    task_mix = str(diagnostics.get("task", ""))
    mean_score = float(diagnostics.get("mean_score", 0.0))
    spread = float(diagnostics.get("spread", 0.0))
    recent_delta = float(diagnostics.get("recent_delta", 0.0))
    mixed_regressed = bool(diagnostics.get("mixed_regressed", False))

    mixed_gsm8k_qasper = ("qasper" in task_mix) and ("gsm8k" in task_mix)

    # In mixed gsm8k+qasper, avoid flipping to bbeh on modest stall signals.
    if mixed_gsm8k_qasper:
        # If spread is low but not ultra-stall, explicitly probe rather than restart/switch.
        if spread < 0.01:
            return (
                "action: explore\n"
                "task: internal:multiobjective_gsm8k\n"
                "max_examples: 8\n"
                "reason: mixed(gsm8k+qasper)+low_spread -> probe gsm8k/qasper (avoid bbeh flip)"
            )
        # If we have headroom, keep exploiting gsm8k.
        if mean_score > 0.3:
            return (
                "action: continue\n"
                "task: internal:multiobjective_gsm8k\n"
                "max_examples: 8\n"
                "reason: mixed task + headroom -> stay on gsm8k"
            )
        return (
            "action: explore\n"
            "task: internal:multiobjective_gsm8k\n"
            "max_examples: 8\n"
            "reason: mixed task -> exploratory gsm8k"
        )

    # If performance is regressing, shift away from a single task
    # and lean on the secondary objective.
    if mixed_regressed and recent_delta < -0.01:
        return (
            "action: exploit\n"
            "task: internal:multiobjective_bbeh\n"
            "max_examples: 10\n"
            "reason: mixed_regressed+strong_negative_delta -> bias toward bbeh"
        )

    # If spread is extremely low, we're likely stalled; switch/restart.
    # Make this stricter so we don't restart too eagerly.
    if spread < 0.003:
        return (
            "action: restart\n"
            "task: internal:multiobjective_bbeh\n"
            "max_examples: 10\n"
            "reason: very_low_spread_stall (ultra-low) -> restart/switch to bbeh"
        )

    # Default: adapt action based on headroom-ish indicators (mean score, spread).
    if mean_score > 0.3 and spread > 0.01:
        return (
            "action: continue\n"
            "task: internal:multiobjective_gsm8k\n"
            "max_examples: 8\n"
            "reason: stable+headroom -> stay on gsm8k"
        )
    if "qasper" in task_mix:
        return (
            "action: explore\n"
            "task: internal:multiobjective_gsm8k\n"
            "max_examples: 8\n"
            "reason: qasper present -> exploratory gsm8k"
        )

    return (
        "action: continue\n"
        "task: internal:multiobjective_gsm8k\n"
        "max_examples: 8\n"
        "reason: default"
    )

